 * <relative-time> — renders a human-readable relative timestamp from an
 * ISO `datetime` attribute and keeps itself fresh on an adaptive timer.
 *
 * Cadence: every 10s while under a minute old, every minute while under
 * an hour, otherwise hourly. Timer is torn down in disconnectedCallback.
 */

const SECOND = 1000;
const MINUTE = 60 * SECOND;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

export class RelativeTimeElement extends HTMLElement {
  static observedAttributes = ['datetime'];

  #timer = null;
  #rtf = null;

  constructor() {
    super();
    // Follow the document language when available; fall back to English so
    // rendering is deterministic in non-browser test environments.
    const lang =
      document.documentElement?.getAttribute('lang') || 'en';
    this.#rtf = new Intl.RelativeTimeFormat(lang, { numeric: 'auto' });
  }

  connectedCallback() {
    this.#render();
  }

  disconnectedCallback() {
    this.#stopTimer();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name !== 'datetime' || oldValue === newValue) return;
    // Attribute may be set before the element is attached to the DOM.
    if (!this.isConnected) return;
    this.#render();
  }

  /** Milliseconds between now and the datetime attribute (positive = past). */
  get #elapsed() {
    const then = new Date(this.getAttribute('datetime')).getTime();
    return Date.now() - then;
  }

  /**
   * Pick the best unit for the elapsed time and format it.
   * Returns { text, unit } where unit drives the refresh cadence.
   */
  #formatRelative(elapsedMs) {
    const seconds = Math.round(elapsedMs / SECOND);
    const abs = Math.abs(seconds);

    if (abs < 60) {
      return { text: this.#rtf.format(-seconds, 'second'), unit: 'second' };
    }
    if (abs < 60 * 60) {
      return {
        text: this.#rtf.format(-Math.round(seconds / 60), 'minute'),
        unit: 'minute',
      };
    }
    if (abs < 60 * 60 * 24) {
      return {
        text: this.#rtf.format(-Math.round(seconds / (60 * 60)), 'hour'),
        unit: 'hour',
      };
    }
    return {
      text: this.#rtf.format(-Math.round(seconds / (60 * 60 * 24)), 'day'),
      unit: 'day',
    };
  }

  #render() {
    if (!this.getAttribute('datetime')) return;

    const elapsedMs = this.#elapsed;
    const { text, unit } = this.#formatRelative(elapsedMs);

    this.textContent = text;

    // Absolute time for tooltips / accessibility.
    const then = new Date(Date.now() - elapsedMs);
    this.setAttribute('title', then.toLocaleString('en-US'));

    this.#scheduleTimer(Math.abs(elapsedMs));
  }

  /** Adaptive interval based on the current unit. */
  #scheduleTimer(elapsedMs) {
    this.#stopTimer();
    const interval =
      elapsedMs < MINUTE ? 10 * SECOND
      : elapsedMs < HOUR ? MINUTE
      : HOUR;
    this.#timer = setInterval(() => this.#render(), interval);
  }

  #stopTimer() {
    if (this.#timer !== null) {
      clearInterval(this.#timer);
      this.#timer = null;
    }
  }
}

if (!customElements.get('relative-time')) {
  customElements.define('relative-time', RelativeTimeElement);
}
"})
