import '../src/relative-time.js';

const NOW = new Date('2026-08-24T12:00:00Z');

function iso(msAgo) {
  return new Date(NOW.getTime() - msAgo).toISOString();
}

function create(msAgo) {
  const el = document.createElement('relative-time');
  el.setAttribute('datetime', iso(msAgo));
  document.body.appendChild(el);
  return el;
}

describe('<relative-time>', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(NOW);
  });

  afterEach(() => {
    vi.useRealTimers();
    document.body.innerHTML = '';
  });

  describe('initial render across unit boundaries', () => {
    it('renders seconds under a minute (45s)', () => {
      const el = create(45 * 1000);
      expect(el.textContent).toBe('45 seconds ago');
    });

    it('renders minutes under an hour (5m)', () => {
      const el = create(5 * 60 * 1000);
      expect(el.textContent).toBe('5 minutes ago');
    });

    it('renders hours under a day (3h)', () => {
      const el = create(3 * 60 * 60 * 1000);
      expect(el.textContent).toBe('3 hours ago');
    });

    it('renders days beyond that (2d)', () => {
      const el = create(2 * 24 * 60 * 60 * 1000);
      expect(el.textContent).toBe('2 days ago');
    });

    it('sets its title attribute to the absolute time', () => {
      const el = create(5 * 60 * 1000);
      expect(el.getAttribute('title')).toContain('2026');
      expect(el.getAttribute('title')).not.toBe('');
    });
  });

  describe('adaptive re-render cadence', () => {
    it('ticks every 10s while under a minute and rolls over to minutes', () => {
      const setIntervalSpy = vi.spyOn(globalThis, 'setInterval');
      const el = create(45 * 1000);

      expect(setIntervalSpy).toHaveBeenLastCalledWith(expect.any(Function), 10_000);

      // +10s: still seconds
      vi.advanceTimersByTime(10_000);
      expect(el.textContent).toBe('55 seconds ago');

      // +10s: crossed the minute boundary — unit switches to minutes
      vi.advanceTimersByTime(10_000);
      expect(el.textContent).toBe('1 minute ago');

      // interval has now adapted to every minute
      expect(setIntervalSpy).toHaveBeenLastCalledWith(expect.any(Function), 60_000);
    });

    it('ticks every minute while under an hour', () => {
      const setIntervalSpy = vi.spyOn(globalThis, 'setInterval');
      const el = create(5 * 60 * 1000);

      expect(setIntervalSpy).toHaveBeenLastCalledWith(expect.any(Function), 60_000);

      // advance in minute steps up to the hour boundary
      for (let i = 0; i < 55; i++) vi.advanceTimersByTime(60_000);
      expect(el.textContent).toBe('1 hour ago');

      // cadence adapted to hourly after crossing into hours
      expect(setIntervalSpy).toHaveBeenLastCalledWith(expect.any(Function), 3_600_000);
    });

    it('ticks hourly once beyond an hour', () => {
      const setIntervalSpy = vi.spyOn(globalThis, 'setInterval');
      create(3 * 60 * 60 * 1000);

      expect(setIntervalSpy).toHaveBeenLastCalledWith(expect.any(Function), 3_600_000);
    });
  });

  describe('cleanup on removal', () => {
    it('clears its timer in disconnectedCallback', () => {
      const clearIntervalSpy = vi.spyOn(globalThis, 'clearInterval');
      const el = create(30 * 1000);

      expect(vi.getTimerCount()).toBe(1);

      el.remove();

      expect(clearIntervalSpy).toHaveBeenCalledTimes(1);
      expect(clearIntervalSpy).toHaveBeenCalledWith(
        expect.anything()
      );
      expect(vi.getTimerCount()).toBe(0);
    });
  });

  describe('attribute-change re-render', () => {
    it('re-renders immediately when datetime changes', () => {
      const el = create(5 * 60 * 1000);
      expect(el.textContent).toBe('5 minutes ago');

      el.setAttribute('datetime', iso(2 * 60 * 60 * 1000));
      expect(el.textContent).toBe('2 hours ago');

      el.setAttribute('datetime', iso(2 * 24 * 60 * 60 * 1000));
      expect(el.textContent).toBe('2 days ago');
