    it('reschedules the adaptive timer on datetime change', () => {
      const setIntervalSpy = vi.spyOn(globalThis, 'setInterval');
      const el = create(5 * 60 * 1000);
      expect(setIntervalSpy).toHaveBeenCalledTimes(1);

      el.setAttribute('datetime', iso(3 * 60 * 60 * 1000));

      expect(setIntervalSpy).toHaveBeenCalledTimes(2);
      expect(setIntervalSpy).toHaveBeenLastCalledWith(expect.any(Function), 3_600_000);
    });
  });
});
